#import "SLImageLoader.h"
#import <ImageIO/ImageIO.h>
@implementation SLImageLoader
+ (SLImageLoader *)shared{static SLImageLoader *s=nil;if(!s)s=[[SLImageLoader alloc]init];return s;}
- (id)init{if((self=[super init])){_cache=[[NSCache alloc]init];_cache.countLimit=120;}return self;}
- (void)load:(NSString *)raw completion:(void (^)(UIImage *))completion{[self load:raw site:2 completion:completion];}
- (void)load:(NSString *)raw site:(NSInteger)site completion:(void (^)(UIImage *))completion{if(![raw isKindOfClass:[NSString class]]||![raw length]){if(completion)completion(nil);return;}NSString *url=nil;if([raw hasPrefix:@"http://"]||[raw hasPrefix:@"https://"])url=raw;else if([raw hasPrefix:@"//"]){NSString *rest=[raw substringFromIndex:2];NSString *host=[[rest componentsSeparatedByString:@"/"]objectAtIndex:0];url=[host rangeOfString:@"."].location!=NSNotFound?[@"https:" stringByAppendingString:raw]:[@"https://img2.imglib.info/" stringByAppendingString:rest];}else{NSString *path=[raw hasPrefix:@"/"]?raw:[@"/" stringByAppendingString:raw];url=[@"https://img2.imglib.info" stringByAppendingString:path];}UIImage *cached=[_cache objectForKey:url];if(cached){if(completion)completion(cached);return;}NSMutableURLRequest *r=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:url] cachePolicy:NSURLRequestReturnCacheDataElseLoad timeoutInterval:25];[r setValue:site==1?@"https://mangalib.me/":@"https://slashlib.me/" forHTTPHeaderField:@"Referer"];[r setValue:[NSString stringWithFormat:@"%ld",(long)(site?site:2)] forHTTPHeaderField:@"Site-Id"];[r setValue:@"image/png,image/jpeg,image/*;q=0.8" forHTTPHeaderField:@"Accept"];[r setValue:@"Mozilla/5.0 (iPhone; CPU iPhone OS 6_1 like Mac OS X) AppleWebKit/536.26 Mobile/10B141 Safari/8536.25" forHTTPHeaderField:@"User-Agent"];[NSURLConnection sendAsynchronousRequest:r queue:[[[NSOperationQueue alloc]init]autorelease] completionHandler:^(NSURLResponse *response,NSData *data,NSError *error){UIImage *image=nil;if(data){CGImageSourceRef src=CGImageSourceCreateWithData((CFDataRef)data,NULL);if(src){NSDictionary *opts=[NSDictionary dictionaryWithObjectsAndKeys:(id)kCFBooleanTrue,(id)kCGImageSourceCreateThumbnailFromImageAlways,[NSNumber numberWithInt:320],(id)kCGImageSourceThumbnailMaxPixelSize,(id)kCFBooleanTrue,(id)kCGImageSourceShouldCache,nil];CGImageRef cg=CGImageSourceCreateThumbnailAtIndex(src,0,(CFDictionaryRef)opts);if(cg){image=[UIImage imageWithCGImage:cg];CGImageRelease(cg);}CFRelease(src);}if(!image)image=[UIImage imageWithData:data];}if(image)[_cache setObject:image forKey:url];dispatch_async(dispatch_get_main_queue(),^{if(completion)completion(image);});}];}
- (void)clear{[_cache removeAllObjects];}
- (void)dealloc{[_cache release];[super dealloc];}
@end
